// ─── src/detect/answer-format.ts ───────────────────────────────────────

// src/detect/answer-format.ts: ask for JSON in the prompt and read it back
// tolerantly, for a model call with no structured-output option (the plugin's
// `$.model.complete`). bench/variants.ts sends the same request shape with
// these two functions, so the plugin's judge is measured as it ships.

/** The instruction appended to a prompt that cannot carry a JSON Schema format. */
const answerAsJson = (schema: unknown): string =>
  `Answer with one JSON object and nothing else. It must match this JSON Schema:\n${JSON.stringify(schema)}`;

/** Parse a JSON answer, allowing a sentence or a code fence around the object. */
function parseLoose<T>(text: string, parse: (t: string) => T): T {
  try {
    return parse(text);
  } catch (first) {
    const a = text.indexOf("{");
    const b = text.lastIndexOf("}");
    if (a >= 0 && b > a) return parse(text.slice(a, b + 1));
    throw first;
  }
}

// ─── src/detect/types.ts ───────────────────────────────────────────────

// src/detect/types.ts: correction-detection domain types (v2)
//
// The unit of detection is a PAIR, not an utterance. This is the direct
// consequence of evals/FINDINGS.md §5: the same string is an instruction at
// the head of a task and a correction right after an Edit. A detector that
// sees only the utterance is structurally incapable of telling them apart.

/** A tool call observed in an assistant turn. */
interface ToolCall {
  /** `tool_use_id` from the transcript, when present. */
  id?: string;
  name: string;
  /** Best-effort target: file path for Edit/Write/Read, command for Bash. */
  target: string;
  /** True when the call mutates user state (Edit/Write/rm/git restore/...). */
  mutating: boolean;
  /** True when the tool reported an error. */
  errored: boolean;
}

/** The assistant turn immediately preceding a user prompt. */
interface PriorTurn {
  /** Concatenated visible text the assistant produced (thinking excluded). */
  text: string;
  toolCalls: ToolCall[];
  /** ISO timestamp of the last event in the turn. */
  endedAt: string | null;
}

/**
 * (prior assistant turn, user prompt): the relational unit a correction
 * judge operates on.
 */
interface Pair {
  pairId: string;
  sessionId: string;
  project: string;
  /** 0-based index among real user prompts in this session. */
  promptIndex: number;
  prompt: string;
  promptAt: string | null;
  prior: PriorTurn | null;
  /** Targets touched in the last few assistant turns, most recent first. */
  recentTargets: string[];
  /** True when the prompt came from a subagent transcript. */
  sidechain: boolean;
}

// ─── Labels: SWE-chat taxonomy (arXiv 2604.20779) ────────────────────
//
// Adopted verbatim so results are directly comparable to a published
// benchmark rather than to a private schema.

const LABELS = [
  "correction", // redirects/adds missing info without rejecting the goal
  "rejection", // explicitly reverts or refuses; asks to restart
  "failure_report", // reports the output is broken/incorrect
  "instruction", // new/continuing task spec, incl. guardrail preambles
  "question", // asks something; not steering away from prior work
  "affirmation", // approves, thanks, confirms
  "other", // pasted blob, noise, meta
] as const;

type Label = (typeof LABELS)[number];

/** The three classes reflect should fire on. */
const PUSHBACK_LABELS: readonly Label[] = [
  "correction",
  "rejection",
  "failure_report",
];

function isPushback(l: Label): boolean {
  return (PUSHBACK_LABELS as readonly string[]).includes(l);
}

interface LabeledPair {
  pairId: string;
  label: Label;
  confidence: "low" | "medium" | "high";
  /** Verbatim span from the prompt that drove the label; "" when none. */
  evidence: string;
  /** One clause of reasoning, kept for human audit, not for scoring. */
  rationale: string;
}

// ─── Stage A: structural gate ────────────────────────────────────────

interface StructuralFeatures {
  hasPriorTurn: boolean;
  isSessionOpener: boolean;
  priorToolCount: number;
  priorMutationCount: number;
  priorErrorCount: number;
  priorAssistantChars: number;
  gapSeconds: number | null;
  promptChars: number;
  promptLines: number;
  /** Prompt mentions a path/basename the prior turn touched. */
  referencesPriorTarget: boolean;
  /** Prompt mentions a target touched in ≥2 of the last 3 turns. */
  referencesThrashTarget: boolean;
  /** Prompt looks like a pasted blob (long, low prose density). */
  looksPasted: boolean;
  /** Prompt contains a fenced code block. */
  hasCodeFence: boolean;
}

interface GateResult {
  /** False ⇒ definitively not a correction; skip all downstream stages. */
  pass: boolean;
  /** 0..1 structural plausibility. Only meaningful when pass is true. */
  score: number;
  /** Why the gate rejected, for audit. */
  reason: string;
  features: StructuralFeatures;
}

// ─── Stage C: relational judge ───────────────────────────────────────

interface JudgeVerdict {
  label: Label;
  confidence: "low" | "medium" | "high";
  evidence: string;
  rationale: string;
}

interface JudgeUsage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens: number;
  cacheCreationTokens: number;
  latencyMs: number;
  model: string;
}

// ─── Cascade ──────────────────────────────────────────────────────────

type CascadeStage = "gate" | "lexical" | "judge";

interface CascadeResult {
  pairId: string;
  /** Final decision: does this prompt count as pushback? */
  pushback: boolean;
  label: Label | null;
  /** Stage that produced the final decision. */
  decidedBy: CascadeStage;
  gate: GateResult;
  lexicalHit: boolean;
  verdict: JudgeVerdict | null;
  usage: JudgeUsage | null;
}

// ─── src/redact.ts ─────────────────────────────────────────────────────

/**
 * Redactor. This file exists twice: `src/redact.ts` is canonical and
 * `web/lib/redact.ts` is its mirror, because the Node package and the Next.js
 * viewer are separate packages. `npm run mirror-check` diffs them and fails
 * the build if they drift; edit the canonical copy and copy it over.
 *
 * Runs on everything reflect stores or sends: each judged message, each tool
 * call target and agent reply the hooks record, each payload to the API.
 * It is pattern matching, so a secret in an unusual format can get through.
 */

const PII_PATTERNS: Array<{ re: RegExp; replacement: string }> = [
  // Home directories in local paths
  { re: /C:\\Users\\[^\\"'\s)]+/gi, replacement: "C:\\Users\\<you>" },
  { re: /C:\\\\Users\\\\[^\\\\"'\s)]+/gi, replacement: "C:\\\\Users\\\\<you>" },
  { re: /\/Users\/[^/"'\s)]+/g, replacement: "/Users/<you>" },
  { re: /\/home\/[^/"'\s)]+/g, replacement: "/home/<you>" },

  // Email addresses
  { re: /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g, replacement: "<email>" },

  // API keys and tokens
  { re: /sk-ant-[A-Za-z0-9_-]{20,}/g, replacement: "<anthropic-key>" },
  { re: /ghp_[A-Za-z0-9]{36}/g, replacement: "<github-token>" },
  { re: /github_pat_[A-Za-z0-9_]{82}/g, replacement: "<github-pat>" },
  { re: /xox[baprs]-[A-Za-z0-9-]+/g, replacement: "<slack-token>" },
  { re: /\bAKIA[0-9A-Z]{16}\b/g, replacement: "<aws-key>" },
  { re: /\bhf_[A-Za-z0-9]{30,}\b/g, replacement: "<hf-token>" },
  { re: /\bnpm_[A-Za-z0-9]{36}\b/g, replacement: "<npm-token>" },
  { re: /\bsk-proj-[A-Za-z0-9_-]{20,}\b/g, replacement: "<openai-key>" },
  { re: /\bAIza[0-9A-Za-z_-]{35}\b/g, replacement: "<google-key>" },

  // Private key blocks
  {
    re: /-----BEGIN [A-Z ]*PRIVATE[ ]KEY-----[\s\S]*?-----END [A-Z ]*PRIVATE[ ]KEY-----/g,
    replacement: "<private-key>",
  },

  // Phone numbers: international form with a leading +, North American
  // (555) 123-4567 and 555-123-4567, and Korean mobile 010-1234-5678.
  { re: /\+\d{1,3}[-. ]?\(?\d{1,4}\)?(?:[-. ]?\d{2,4}){2,4}\b/g, replacement: "<phone>" },
  { re: /(?:\(\d{3}\)\s?|\b\d{3}[-. ])\d{3}[-. ]\d{4}\b/g, replacement: "<phone>" },
  { re: /\b01[016789][-. ]?\d{3,4}[-. ]?\d{4}\b/g, replacement: "<phone>" },
];

/**
 * Replace unpaired UTF-16 surrogates with U+FFFD.
 *
 * A message can contain a lone surrogate: a truncated emoji, a paste cut
 * mid-codepoint, a byte-sliced log line. `JSON.stringify` will happily emit it,
 * and the API then rejects the whole request with
 * `no low surrogate in string`. Observed once in 836 real prompts; without this
 * the judge simply cannot classify that turn, forever, with no way to recover.
 */
function stripLoneSurrogates(input: string): string {
  if (!input) return input;
  // Match a high surrogate not followed by a low one, or a low one not
  // preceded by a high one.
  return input.replace(/[\uD800-\uDBFF](?![\uDC00-\uDFFF])|(?<![\uD800-\uDBFF])[\uDC00-\uDFFF]/g, "\uFFFD");
}

/**
 * Truncate to `max` UTF-16 code units without splitting a surrogate pair.
 *
 * `String.prototype.slice` cuts by code unit, so a boundary that lands inside
 * an astral character (emoji, some CJK extensions) leaves a lone surrogate,
 * and the API rejects the entire request with `no low surrogate in string`.
 * Repairing the input before slicing does not help, because the slice is what
 * creates the damage. Every truncation of user-supplied text on the way to the
 * API must go through this.
 */
function safeTruncate(input: string, max: number): string {
  if (input.length <= max) return input;
  let end = max;
  const c = input.charCodeAt(end - 1);
  if (c >= 0xd800 && c <= 0xdbff) end -= 1; // do not orphan a high surrogate
  return input.slice(0, end);
}

/**
 * Keep the LAST `max` code units without orphaning a low surrogate.
 *
 * The mirror of `safeTruncate`. Needed wherever a tail is the meaningful
 * part: an assistant turn's ending, a log's most recent lines.
 */
function safeTruncateEnd(input: string, max: number): string {
  if (input.length <= max) return input;
  let start = input.length - max;
  const c = input.charCodeAt(start);
  if (c >= 0xdc00 && c <= 0xdfff) start += 1; // do not orphan a low surrogate
  return input.slice(start);
}

function redactString(input: string): string {
  if (!input) return input;
  let out = stripLoneSurrogates(input);
  for (const { re, replacement } of PII_PATTERNS) {
    out = out.replace(re, replacement);
  }
  return out;
}

function redactObject<T>(input: T): T {
  if (input === null || input === undefined) return input;
  if (typeof input === "string") return redactString(input) as unknown as T;
  if (Array.isArray(input)) return input.map(redactObject) as unknown as T;
  if (typeof input === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(input as Record<string, unknown>)) {
      out[k] = redactObject(v);
    }
    return out as T;
  }
  return input;
}

// ─── src/detect/render.ts ──────────────────────────────────────────────

// src/detect/render.ts: how the judge sees the agent's previous turn.
// Moved out of judge.ts unchanged so the hooks can summarise a turn without
// loading the SDK. PRIOR_TEXT_CHARS is part of judgeFingerprint().


const PRIOR_TEXT_CHARS = 1400;

function renderPriorTurn(pair: Pair): string {
  const prior = pair.prior;
  if (!prior) return "(The agent has not spoken yet in this session.)";

  const calls = prior.toolCalls;
  const mut = calls.filter((c) => c.mutating).length;
  const err = calls.filter((c) => c.errored).length;

  const lines: string[] = [];
  if (calls.length) {
    const shown = calls.slice(-14);
    lines.push(
      `Agent actions this turn (${calls.length} total, ${mut} modified files, ${err} errored)` +
        (calls.length > shown.length ? `, last ${shown.length} shown:` : ":"),
    );
    for (const c of shown) {
      const flags = `${c.mutating ? " [modified]" : ""}${c.errored ? " [error]" : ""}`;
      lines.push(`  - ${c.name}: ${safeTruncate(redactString(c.target), 120)}${flags}`);
    }
  } else {
    lines.push("Agent actions this turn: none (it replied without using tools).");
  }

  const text = redactString(prior.text).trim();
  if (text) {
    const tail =
      text.length > PRIOR_TEXT_CHARS
        ? "…" + safeTruncateEnd(text, PRIOR_TEXT_CHARS)
        : text;
    lines.push("", "What the agent said, ending its turn:", '"""', tail, '"""');
  } else {
    lines.push("", "The agent produced no visible text this turn.");
  }

  return lines.join("\n");
}

