// src/models.ts: every model id reflect names, in one module with no imports,
// so the hooks that never call a model can read them without loading the SDK.

/** The judge the hook runs. Claude Haiku 5.5: $0.10 / $0.50 per MTok, 512-token cache floor. */
const DEFAULT_JUDGE_MODEL = "claude-haiku-5-5";
/**
 * The models behind the 2026-08 benchmark. Pinned by id in bench/label.ts so a
 * change to the product default can never relabel the reference silently.
 */
const BENCH_PROD_MODEL = "claude-haiku-4-5";
const REFERENCE_JUDGE_MODEL = "claude-opus-5";

/** The reflection, written only when pushback clusters. */
const DEFAULT_REFLECTION_MODEL = "claude-opus-5-5";
const DEFAULT_REFLECTION_EFFORT = "high";

// ─── src/pricing.ts ────────────────────────────────────────────────────

// src/pricing.ts: model catalogue and cost arithmetic.
//
// Replaced the hardcoded 2026-04 Opus 4.7 constants that v0.1 inlined in its
// reflection client (debt item D7). Prices are USD per million tokens,
// Anthropic first-party API rates. Partner platforms (Bedrock, Vertex) bill
// separately and are out of scope here.
//
// Cache multipliers are ratios of the input rate, which is how Anthropic
// documents them and how they stay correct when a model's base rate changes:
//   read 0.1x · 5-minute write 1.25x · 1-hour write 2.0x

interface ModelPrice {
  /** USD per million input tokens. */
  input: number;
  /** USD per million output tokens. */
  output: number;
  /** Context window in tokens. */
  context: number;
  /**
   * USD per million cache-read tokens, when the model's rate is not the usual
   * 0.1x of input. Claude Opus 5.5 and Sonnet 5.5 read at 0.05x, Fable 5.2 at
   * 0.025x.
   */
  cacheRead?: number;
}

const CACHE_READ_MULTIPLIER = 0.1;
const CACHE_WRITE_5M_MULTIPLIER = 1.25;
const CACHE_WRITE_1H_MULTIPLIER = 2.0;

/**
 * Catalogue snapshot: 2026-11-16, from the claude-api reference table cached
 * 2026-11-03. Verify against the pricing page before publishing numbers.
 *
 * Claude Haiku 5.5 is $0.10 / $0.50 for prompts up to 100K tokens and
 * $0.50 / $2.50 beyond; reflect's judge prompts are ~5K, so the lower tier is
 * the one listed.
 *
 * Frozen: `priceFor` hands the entry straight back, so an unfrozen object lets
 * one careless caller silently reprice every subsequent cost calculation in the
 * process.
 */
const PRICES: Readonly<Record<string, Readonly<ModelPrice>>> = Object.freeze({
  "claude-fable-5-2": { input: 8, output: 40, context: 1_000_000, cacheRead: 0.2 },
  "claude-fable-5-1": { input: 10, output: 50, context: 1_000_000, cacheRead: 0.25 },
  "claude-fable-5": { input: 10, output: 50, context: 1_000_000 },
  "claude-opus-5-5": { input: 4, output: 20, context: 1_000_000, cacheRead: 0.2 },
  "claude-opus-5": { input: 5, output: 25, context: 1_000_000 },
  "claude-opus-4-8": { input: 5, output: 25, context: 1_000_000 },
  "claude-opus-4-7": { input: 5, output: 25, context: 1_000_000 },
  "claude-opus-4-6": { input: 5, output: 25, context: 1_000_000 },
  "claude-sonnet-5-5": { input: 2, output: 10, context: 1_000_000, cacheRead: 0.1 },
  "claude-sonnet-5": { input: 2, output: 10, context: 1_000_000 },
  "claude-sonnet-4-6": { input: 3, output: 15, context: 1_000_000 },
  "claude-haiku-5-5": { input: 0.1, output: 0.5, context: 1_000_000 },
  "claude-haiku-4-5": { input: 1, output: 5, context: 200_000 },
} as Record<string, ModelPrice>);
for (const v of Object.values(PRICES)) Object.freeze(v);

const PRICES_AS_OF = "2026-11-16";

/** Resolve a dated snapshot id (claude-haiku-4-5-20251001) to its base entry. */
function priceFor(model: string): Readonly<ModelPrice> {
  const exact = PRICES[model];
  if (exact) return exact;
  const base = model.replace(/-\d{8}$/, "");
  const stripped = PRICES[base];
  if (stripped) return stripped;
  throw new Error(`unknown model for pricing: ${model} (add it to src/pricing.ts)`);
}

interface TokenUsage {
  inputTokens: number;
  outputTokens: number;
  cacheReadTokens?: number;
  cacheCreation5mTokens?: number;
  cacheCreation1hTokens?: number;
}

function costUSD(model: string, u: TokenUsage): number {
  const p = priceFor(model);
  const m = 1 / 1_000_000;
  return (
    u.inputTokens * p.input * m +
    u.outputTokens * p.output * m +
    (u.cacheReadTokens ?? 0) * (p.cacheRead ?? p.input * CACHE_READ_MULTIPLIER) * m +
    (u.cacheCreation5mTokens ?? 0) * p.input * CACHE_WRITE_5M_MULTIPLIER * m +
    (u.cacheCreation1hTokens ?? 0) * p.input * CACHE_WRITE_1H_MULTIPLIER * m
  );
}

/**
 * For spend caps. An unknown model id is charged at the most expensive entry in
 * the table instead of throwing, so a cap with an unlisted model still trips.
 */
function capCostUSD(model: string, u: TokenUsage): number {
  try {
    return costUSD(model, u);
  } catch {
    const top = Object.keys(PRICES).reduce((a, b) => ((PRICES[b]?.output ?? 0) > (PRICES[a]?.output ?? 0) ? b : a));
    return costUSD(top, u);
  }
}

function formatUSD(v: number): string {
  if (v === 0) return "$0";
  if (v < 0.01) return `$${v.toFixed(5)}`;
  if (v < 1) return `$${v.toFixed(4)}`;
  return `$${v.toFixed(2)}`;
}

// ─── src/reflect/schema.ts ─────────────────────────────────────────────

// src/reflect/schema.ts: what a v0.2 reflection is.
//
// v0.1 asked for {pattern, signal, adjustment, confidence, scope,
// false_trigger_likelihood} and parsed it out of free text with a fence regex.
// v0.2 keeps those six fields, adds three that make a reflection checkable
// rather than merely confident, and gets them through structured output.
//
//   counter_hypothesis  the strongest reading under which this reflection is
//                       wrong. Self-reflection systems that skip this lock in
//                       a bad generalisation and stop collecting the evidence
//                       that would overturn it (the ExpeL failure mode).
//   verify              one cheap check the agent can run before applying the
//                       adjustment.
//   expires_after_turns guidance is about this stretch of work, not forever.

type Level = "low" | "medium" | "high";

interface Reflection2 {
  pattern: string;
  signal: string;
  adjustment: string;
  confidence: Level;
  scope: "this_session" | "wider_concern";
  false_trigger_likelihood: Level;
  counter_hypothesis: string;
  verify: string;
  expires_after_turns: number;
}

const MIN_EXPIRY_TURNS = 3;
const MAX_EXPIRY_TURNS = 12;
const DEFAULT_EXPIRY_TURNS = 8;

const REFLECTION_SCHEMA = {
  type: "object",
  properties: {
    pattern: {
      type: "string",
      description: "What the agent kept doing across the pushback turns, stated causally. Two sentences at most.",
    },
    signal: {
      type: "string",
      description: "What the developer was objecting to, in their terms, citing the turns.",
    },
    adjustment: {
      type: "string",
      description: "One concrete change the agent should make for the rest of this session. Imperative, specific, checkable.",
    },
    confidence: { type: "string", enum: ["low", "medium", "high"] },
    scope: { type: "string", enum: ["this_session", "wider_concern"] },
    false_trigger_likelihood: { type: "string", enum: ["low", "medium", "high"] },
    counter_hypothesis: {
      type: "string",
      description: "The strongest reading of the same turns under which this reflection is wrong.",
    },
    verify: {
      type: "string",
      description: "One cheap check the agent can make before applying the adjustment (re-read a file, ask one question, run one test).",
    },
    expires_after_turns: {
      type: "integer",
      description: "How many more developer turns this guidance should stay in force, between 3 and 12.",
    },
  },
  required: [
    "pattern",
    "signal",
    "adjustment",
    "confidence",
    "scope",
    "false_trigger_likelihood",
    "counter_hypothesis",
    "verify",
    "expires_after_turns",
  ],
  additionalProperties: false,
} as const;

const LEVELS = new Set(["low", "medium", "high"]);

function str(v: unknown, max: number): string {
  return typeof v === "string" ? v.trim().slice(0, max) : "";
}

/**
 * Validate and clamp. Structured output is a server-side contract; this is the
 * client-side check that the contract held, because a harness that trusts what
 * it has not checked is how v0.1's parser survived as long as it did.
 */
function parseReflection2(text: string): Reflection2 {
  let obj: Record<string, unknown>;
  try {
    obj = JSON.parse(text.trim()) as Record<string, unknown>;
  } catch {
    throw new Error(`reflection was not JSON: ${text.slice(0, 160)}`);
  }
  if (!obj || typeof obj !== "object") throw new Error("reflection was not an object");
  const level = (v: unknown, name: string): Level => {
    if (typeof v === "string" && LEVELS.has(v)) return v as Level;
    throw new Error(`reflection field ${name} out of enum: ${String(v)}`);
  };
  const scope = obj["scope"] === "wider_concern" ? "wider_concern" : "this_session";
  const rawExpiry = Number(obj["expires_after_turns"]);
  const expiry = Number.isFinite(rawExpiry)
    ? Math.min(MAX_EXPIRY_TURNS, Math.max(MIN_EXPIRY_TURNS, Math.round(rawExpiry)))
    : DEFAULT_EXPIRY_TURNS;
  const r: Reflection2 = {
    pattern: str(obj["pattern"], 600),
    signal: str(obj["signal"], 600),
    adjustment: str(obj["adjustment"], 600),
    confidence: level(obj["confidence"], "confidence"),
    scope,
    false_trigger_likelihood: level(obj["false_trigger_likelihood"], "false_trigger_likelihood"),
    counter_hypothesis: str(obj["counter_hypothesis"], 400),
    verify: str(obj["verify"], 300),
    expires_after_turns: expiry,
  };
  if (!r.adjustment) throw new Error("reflection has no adjustment");
  return r;
}

// ─── src/reflect/format.ts ─────────────────────────────────────────────

// src/reflect/format.ts: how a reflection is shown to the agent and to the developer.
//
// v0.1 wrote a markdown file and hoped a path-scoped rule would make the agent
// read it. v0.2 hands the text to the agent directly through a hook's
// `additionalContext` (limit 10,000 characters; we stay far below it) and still
// writes the file, which is now for the developer.


const MAX_CONTEXT_CHARS = 2400;

interface GuidanceMeta {
  pushbacks: number;
  window: number;
  /** 1-based developer turns the reflection was built from. */
  turns: number[];
  manual?: boolean;
}

function clip(s: string, n: number): string {
  return s.length > n ? s.slice(0, n - 1) + "…" : s;
}

function formatForAgent(r: Reflection2, meta: GuidanceMeta): string {
  const head = meta.manual
    ? "reflect: the developer asked for a reflection on this session. An outside reviewer read the recent turns and suggests:"
    : `reflect: the developer has pushed back on ${meta.pushbacks} of their last ${meta.window} turns` +
      (meta.turns.length ? ` (turns ${meta.turns.join(", ")})` : "") +
      ". An outside reviewer read those turns and suggests:";
  const hedge =
    r.confidence === "low" || r.false_trigger_likelihood === "high"
      ? "Treat the adjustment as a question: ask the developer before acting on it."
      : r.confidence === "medium"
        ? "Apply the adjustment, and say briefly that you are doing so."
        : "Apply the adjustment.";
  const lines = [
    head,
    "",
    `Pattern: ${r.pattern}`,
    `What the pushback is about: ${r.signal}`,
    `Adjustment for the next ${r.expires_after_turns} turns: ${r.adjustment}`,
    r.verify ? `Before applying it: ${r.verify}` : "",
    "",
    `Confidence ${r.confidence}, false-trigger likelihood ${r.false_trigger_likelihood}.` +
      (r.counter_hypothesis ? ` It may be wrong if: ${r.counter_hypothesis}` : ""),
    hedge,
    r.scope === "wider_concern"
      ? "This looks like a standing project convention. You may suggest recording it in CLAUDE.md; do not edit CLAUDE.md unasked."
      : "",
    "The developer's own words in the current turn take precedence over this note.",
  ].filter((l, i, a) => !(l === "" && (i === 0 || a[i - 1] === "")));
  return clip(lines.join("\n").trim(), MAX_CONTEXT_CHARS);
}

function formatMarkdown(
  r: Reflection2,
  meta: GuidanceMeta & { at: string; model: string; costUSD: number },
): string {
  return [
    `# Session reflection: ${meta.at}`,
    "",
    meta.manual
      ? "Requested manually."
      : `Triggered by pushback on ${meta.pushbacks} of the last ${meta.window} developer turns (${meta.turns.join(", ")}).`,
    "",
    "## What I was doing (pattern)",
    r.pattern,
    "",
    "## Why the developer pushed back (signal)",
    r.signal,
    "",
    `## Adjustment for the next ${r.expires_after_turns} turns`,
    r.adjustment,
    "",
    "## Check before applying",
    r.verify || "(none)",
    "",
    "## If this is wrong",
    r.counter_hypothesis || "(none given)",
    "",
    `> Confidence: ${r.confidence} · Scope: ${r.scope} · FT-likelihood: ${r.false_trigger_likelihood} · ` +
      `${meta.model} · $${meta.costUSD.toFixed(4)}`,
    "",
  ].join("\n");
}

// ─── src/reflect/reflection-prompt.ts ──────────────────────────────────

// src/reflect/reflection-prompt.ts: what the reflection model is asked.
//
// No I/O and no SDK: src/reflect/reflection.ts sends it through the API, and
// the plugin's mod through Claude Code's own model client (`npm run build`
// writes it into plugin/hooks/reflect.ts with the mod).


const REFLECTION_SYSTEM = `You are reflect, a reviewer that watches a long Claude Code session from the outside.

You are called only when a separate classifier has found that the developer pushed back on the agent more than once within a few turns. You receive those turns: what the agent had just done, what the developer said next, and the words the classifier took as evidence. You do not see the rest of the session.

Your job is to name what the agent is repeatedly missing, so that the next turns stop producing the same objection. The developer's individual messages are already in the agent's context. What the agent lacks is the view across them: the thing they have in common.

How to read the turns:
- Treat the developer's words as the primary evidence and the agent's actions as context. Quote short spans when they decide the question.
- Look for the shared cause. "You changed files I did not ask about" twice is a scope problem, not two unrelated mistakes. "That's not what I meant" after two different edits may be one misunderstood requirement.
- The classifier can be wrong. A message can look like a correction and be a new instruction, a question, or a change of mind. If the turns do not share a cause, say so: set confidence low and false_trigger_likelihood high, and make the adjustment a question the agent should ask rather than a rule it should follow.
- Prefer adjustments the agent can act on in the very next turn: re-read a named file before editing it, confirm scope before touching more than one file, stop and ask before reverting, keep an explicit constraint the developer stated. Avoid generic advice such as "be more careful" or "follow instructions".
- Do not restate the developer's last message as the adjustment. They already said it; the agent already has it.
- scope is "wider_concern" only when the pattern is likely to recur in future sessions too (a project convention the agent keeps violating, for example). Otherwise "this_session".
- counter_hypothesis is the best alternative reading of the same turns under which your reflection would mislead the agent. Write it seriously: it is shown to the agent next to your adjustment.
- expires_after_turns: how many more developer turns the guidance should stay in force. Short (3 to 5) for a local misunderstanding, longer (8 to 12) for a standing constraint.

Write every field in the language the developer uses in the quoted turns. Keep each field to two sentences or fewer.`;

interface EvidenceTurn {
  /** 1-based position among the developer's turns in this session. */
  turn: number;
  label: string;
  confidence: string;
  /** The judge's rendering of what the agent had just done. */
  priorSummary: string;
  prompt: string;
  evidence: string;
}

const EVIDENCE_PRIOR_CHARS = 1500;
const EVIDENCE_PROMPT_CHARS = 1500;

function buildReflectionInput(turns: EvidenceTurn[], window: number, intro?: string): string {
  const lines: string[] = [
    intro ?? `The developer pushed back on ${turns.length} of their last ${window} turns. Oldest first.`,
    "",
  ];
  for (const t of turns) {
    const prior = redactString(t.priorSummary).trim();
    lines.push(
      `## Developer turn ${t.turn}: classified ${t.label} (${t.confidence} confidence)`,
      "",
      "What the agent had just done:",
      prior.length > EVIDENCE_PRIOR_CHARS ? "…" + safeTruncateEnd(prior, EVIDENCE_PRIOR_CHARS) : prior || "(nothing recorded)",
      "",
      "What the developer said next:",
      '"""',
      safeTruncate(redactString(t.prompt), EVIDENCE_PROMPT_CHARS),
      '"""',
      t.evidence ? `Classifier's evidence span: "${safeTruncate(redactString(t.evidence), 240)}"` : "",
      "",
    );
  }
  lines.push("Write the reflection.");
  return lines.filter((l, i, a) => !(l === "" && a[i - 1] === "")).join("\n");
}

// ─── src/transcript/text.ts ────────────────────────────────────────────

// src/transcript/text.ts: reading a prompt's text and a tool call's target.
//
// No I/O: the transcript parser, the CLI's hooks and the plugin's mod use it
// (`npm run build` writes it into plugin/hooks/reflect.ts with the mod).

// ─── Mutation classification ──────────────────────────────────────────

const MUTATING_TOOLS = new Set([
  "Edit",
  "Write",
  "MultiEdit",
  "NotebookEdit",
  "str_replace_based_edit_tool",
]);

/**
 * Bash commands that change user-visible state. Deliberately broader than the
 * shipped Tier 1/2 regexes: this feeds Stage A's structural prior, not the
 * shipped weighted accumulator.
 */
const MUTATING_BASH =
  /(^|[;&|]\s*)(rm|unlink|mv|cp|mkdir|touch|git\s+(revert|restore|checkout|reset|apply|commit|add|rm|mv)|sed\s+-i|npm\s+(i|install|uninstall|publish)|pnpm\s+(add|remove)|yarn\s+(add|remove)|pip\s+install|dd|truncate|chmod|chown)\b|>\s*[^|&\s]/;

function isMutating(name: string, input: Record<string, unknown>): boolean {
  if (MUTATING_TOOLS.has(name)) return true;
  if (name === "Bash" || name === "PowerShell") {
    const cmd = String(input["command"] ?? "");
    return MUTATING_BASH.test(cmd);
  }
  return false;
}

function toolTarget(name: string, input: Record<string, unknown>): string {
  const fp = input["file_path"] ?? input["path"] ?? input["notebook_path"];
  if (typeof fp === "string" && fp) return fp;
  if (name === "Bash" || name === "PowerShell") {
    return String(input["command"] ?? "").slice(0, 200);
  }
  const pat = input["pattern"] ?? input["query"] ?? input["description"] ?? input["url"];
  if (typeof pat === "string" && pat) return pat.slice(0, 200);
  return "";
}

// ─── Prompt text ──────────────────────────────────────────────────────

/**
 * Strip harness-injected wrappers that are not user prose.
 *
 * Measured on 1,166 raw prompts from 226 local sessions: 233 of them (20%) are
 * ENTIRELY harness injection: `<task-notification>` background-task events
 * (219), `<bash-input>`/`<bash-stdout>` from `!` commands (10), and others.
 * A further 106 are a hook-injected context preamble (`<november-context>`)
 * followed by real user prose, so the block must be stripped without dropping
 * the prompt.
 *
 * The discriminator is structural, not a hand-maintained denylist: every
 * harness channel Claude Code emits uses a HYPHENATED tag name
 * (`task-notification`, `system-reminder`, `local-command-caveat`,
 * `bash-input`), while ordinary HTML a user might quote does not (`div`, `p`,
 * `code`). The HTML spec reserves hyphenated names for custom elements, so
 * this stays true for quoted markup as well. Fenced code is masked first so a
 * user pasting `<my-widget>` inside a fence survives.
 */
const EXTRA_WRAPPER_TAGS = [
  "command-name",
  "command-message",
  "command-args",
  "ide_opened_file",
  "ide_selection",
];

const HYPHENATED_BLOCK = /<([a-z][a-z0-9]*(?:-[a-z0-9]+)+)(?:\s[^>]*)?>[\s\S]*?<\/\1>/g;
/** Truncated / unclosed injection: a hyphenated open tag with no partner. */
const HYPHENATED_OPEN_TAIL = /<([a-z][a-z0-9]*(?:-[a-z0-9]+)+)(?:\s[^>]*)?>[\s\S]*$/;
const FENCE = /```[\s\S]*?```|~~~[\s\S]*?~~~/g;

/**
 * Channels Claude Code is known to inject. Used ONLY for the destructive
 * unclosed-tag path; the balanced-block strip above stays structural.
 */
const KNOWN_HARNESS_TAGS = new Set([
  "task-notification", "system-reminder", "local-command-caveat",
  "local-command-stdout", "local-command-stderr", "bash-input",
  "bash-stdout", "bash-stderr", "user-prompt-submit-hook",
  "command-name", "command-message", "command-args",
]);

function stripWrappers(s: string): string {
  // 1. Mask fenced code so quoted markup is never touched. The sentinel is a
  //    Private Use Area codepoint: it cannot collide with anything a developer
  //    types, and unlike the NUL that was here before it does not turn this
  //    source file into something `grep` reports as binary.
  const fences: string[] = [];
  let out = s.replace(FENCE, (m) => {
    fences.push(m);
    return `\uE000FENCE${fences.length - 1}\uE000`;
  });

  // 2. balanced hyphenated blocks, repeatedly (they nest in practice)
  for (let i = 0; i < 4; i++) {
    const next = out.replace(HYPHENATED_BLOCK, " ");
    if (next === out) break;
    out = next;
  }

  // 3. explicit non-hyphenated harness tags
  for (const tag of EXTRA_WRAPPER_TAGS) {
    // In a template literal "\s" is just "s": the backslashes must be doubled
    // (until 2026-11-16 they were not, and IDE blocks reached the judge).
    out = out.replace(new RegExp(`<${tag}>[\\s\\S]*?</${tag}>`, "g"), " ");
    out = out.replace(new RegExp(`<${tag}\\s*/>`, "g"), " ");
  }

  // 4. A leading UNCLOSED injection block (transcript truncation). This deletes
  //    everything after the tag, so it fires only on channels known to be
  //    harness output. Matching any hyphenated name would silently erase the
  //    whole prompt of anyone opening with `<my-widget>` or `<x-foo>`, which is
  //    ordinary vocabulary for a front-end developer.
  const lead = /^\s*<([a-z][a-z0-9]*(?:-[a-z0-9]+)+)/.exec(out);
  if (lead && KNOWN_HARNESS_TAGS.has(lead[1] as string)) {
    out = out.replace(HYPHENATED_OPEN_TAIL, " ");
  }

  // 5. Normalise whitespace BEFORE unmasking. Doing it afterwards undid the
  //    entire point of masking: it collapsed the indentation of every fenced
  //    code block the user pasted, changing both `promptChars` (a scored
  //    feature) and the text the judge reads.
  out = out.replace(/[ \t]+/g, " ").replace(/\n{3,}/g, "\n\n").trim();

  // 6. unmask
  out = out.replace(/\uE000FENCE(\d+)\uE000/g, (_m, i) => fences[Number(i)] ?? "");

  return out;
}


/**
 * Minimum residual prose for a stripped prompt to count as user-authored.
 * Below this the event was pure harness traffic and the pair is dropped.
 */
const MIN_PROMPT_CHARS = 3;

/**
 * Auto-compaction writes its summary into the transcript as a `user` message.
 * Measured at 87 of 933 prompts (9.3%) in the local corpus, and they are the
 * longest messages present, so leaving them in would poison every
 * length-derived feature as well as the label distribution.
 */
const COMPACTION_CONTINUATION =
  /^\s*This session is being continued from a previous conversation/i;

/**
 * Bookkeeping slash commands. These are UI operations, not task interaction.
 * Task-bearing slash commands (`/undo`, `/rewind`, `/brain-reflect`, project
 * commands) are deliberately NOT listed: `/undo` in particular is a rejection
 * signal reflect should learn to read.
 */
const BOOKKEEPING_COMMANDS = new Set([
  "compact", "clear", "cost", "status", "resume", "exit", "quit", "help",
  "model", "config", "doctor", "login", "logout", "usage", "context",
  "export", "init", "terminal-setup", "vim", "statusline", "privacy-settings",
  "release-notes", "upgrade", "migrate-installer", "install-github-app",
]);

/** True when the event is harness bookkeeping rather than a user turn. */
function isBookkeeping(prompt: string): boolean {
  const t = prompt.trim();
  if (COMPACTION_CONTINUATION.test(t)) return true;
  const m = /^\/([a-zA-Z0-9:_-]+)\s*(.*)$/s.exec(t);
  if (m && BOOKKEEPING_COMMANDS.has((m[1] as string).toLowerCase())) {
    // `/compact some instructions` still carries user intent; bare does not.
    return (m[2] ?? "").trim().length < MIN_PROMPT_CHARS;
  }
  return false;
}

// ─── src/trigger/accumulator.ts ────────────────────────────────────────

// src/trigger/accumulator.ts: when does a run of pushback verdicts become a reflection?
//
// v0.1.4 summed weighted signals into one monotonic integer and fired at 240.
// Replayed on real sessions it never fired (evals/FINDINGS.md, bench/FINDINGS.md):
// the weights assumed a user who reverts with git, and the integer never
// decayed, so the few signals it did see were spread across hours.
//
// v0.2 counts judged pushback turns inside a sliding window of USER TURNS. One
// correction is already in front of the agent, verbatim; reflecting on it adds
// little. Two inside a short window are a pattern the agent is not seeing,
// which is the thing a reflection can name. Policies are data so that
// bench/session-sim.ts can replay every one of them over cached verdicts.


type Confidence = "low" | "medium" | "high";

interface TriggerPolicy {
  id: string;
  /** Pushback turns needed inside the window. */
  k: number;
  /** Window length in user turns, counting the current one. */
  window: number;
  /** User turns after a fire during which nothing can fire. */
  cooldown: number;
  /** Verdicts below this confidence are ignored. */
  minConfidence?: Confidence;
  /** The shipped default. Exactly one policy carries it. */
  isDefault?: boolean;
}

/**
 * Candidate policies. The default was chosen by bench/session-sim.ts on the
 * 2026-08 corpus, which is in-sample; the replay table is published next to
 * it so the choice can be argued with.
 */
const TRIGGER_POLICIES: readonly TriggerPolicy[] = Object.freeze([
  { id: "each", k: 1, window: 1, cooldown: 0 },
  { id: "k2w4", k: 2, window: 4, cooldown: 3 },
  { id: "k2w6", k: 2, window: 6, cooldown: 3, isDefault: true },
  { id: "k2w8", k: 2, window: 8, cooldown: 3 },
  { id: "k3w8", k: 3, window: 8, cooldown: 3 },
  { id: "k2w6-med", k: 2, window: 6, cooldown: 3, minConfidence: "medium" },
]);

function defaultPolicy(): TriggerPolicy {
  const p = TRIGGER_POLICIES.find((x) => x.isDefault);
  if (!p) throw new Error("no default trigger policy");
  return p;
}

function policyById(id: string | undefined): TriggerPolicy {
  if (!id) return defaultPolicy();
  return TRIGGER_POLICIES.find((p) => p.id === id) ?? defaultPolicy();
}

const RANK: Record<Confidence, number> = { low: 0, medium: 1, high: 2 };

interface PushbackSignal {
  label: Label;
  confidence: Confidence;
}

interface Fire {
  /** Ids of the turns whose verdicts tripped the trigger, oldest first. */
  evidence: string[];
  policyId: string;
}

/**
 * Pure state machine. Feed it every user turn in order, with `null` for turns
 * that were not judged or were not pushback. Deterministic, so the hook and
 * the replay agree by construction.
 */
class Accumulator {
  private readonly policy: TriggerPolicy;
  /** Turn ordinals (0-based) and ids of retained pushback turns. */
  private hits: Array<{ turn: number; id: string }> = [];
  private turn = -1;
  private cooldownUntil = -1;

  constructor(policy: TriggerPolicy) {
    this.policy = policy;
  }

  observe(id: string, signal: PushbackSignal | null): Fire | null {
    this.turn++;
    const p = this.policy;
    const counts =
      signal !== null && RANK[signal.confidence] >= RANK[p.minConfidence ?? "low"];
    if (counts) this.hits.push({ turn: this.turn, id });
    // Drop hits that slid out of the window.
    this.hits = this.hits.filter((h) => this.turn - h.turn < p.window);

    if (this.turn <= this.cooldownUntil) return null;
    if (!counts || this.hits.length < p.k) return null;

    const fire: Fire = { evidence: this.hits.map((h) => h.id), policyId: p.id };
    this.hits = [];
    this.cooldownUntil = this.turn + p.cooldown;
    return fire;
  }
}

// ─── src/mod/reflect.ts ────────────────────────────────────────────────

// src/mod/reflect.ts: reflect as a Claude Code mod (function hooks).
//
// For each message the developer sends, reflect pairs it with what the agent
// did just before and asks Claude Haiku 5.5 whether the message pushes back on
// the agent. When two messages within six turns do, Claude Opus 5.5 reads those
// turns and writes a short note on what the agent keeps missing. The note goes
// to the agent once, with its next tool result or the developer's next message,
// and the developer sees the same note word for word in the transcript.
//
// Everything goes through Claude Code. The model calls use the session's own
// model client ($.model.complete), billed like the session's other requests,
// so the plugin has no API key, no network access of its own, no shell command
// and no file access, and it never reads the transcript. What it keeps lives
// in memory for the session and is gone when the session ends.
//
// The plugin's plugin/hooks/reflect.ts is generated from this file and the
// src/ modules it imports (scripts/build-hook.mjs), so the plugin ships one
// code file and judges and reflects with the same prompts as the npm package.


const POLICY = defaultPolicy();
const DEFAULT_MAX_USD = 0.5;
/** Judged messages whose text is kept for a reflection, as in the npm package. */
const KEPT_TEXTS = 12;
const MAX_CALLS_PER_TURN = 50;
const MAX_AGENT_TEXT = 4000;
/** A context under half its size at the last look means the conversation was compacted. */
const COMPACTED_BELOW = 0.5;
const COMPACTION_FLOOR_TOKENS = 20_000;

/** Where a developer's own message comes from: typed, sent from a phone or web client, or a `claude -p` turn. */
const DEVELOPER_ORIGINS = new Set(["composer", "bridge", "sdk"]);
/** What an alias costs, for the spend cap, if the engine had to fall back to one. */
const ALIAS_PRICED_AS: Record<string, string> = {
  haiku: DEFAULT_JUDGE_MODEL,
  opus: DEFAULT_REFLECTION_MODEL,
  sonnet: "claude-sonnet-5-5",
};

const SHOWN_HEAD = "reflect sent the agent this note:";
const STATUS_COMMAND = "reflect-status";
const SHOWN_AGAIN = "reflect sent the agent its current note again, because the conversation was compacted:";

interface Verdict {
  label: Label;
  confidence: JudgeVerdict["confidence"];
}

interface TurnText {
  prompt: string;
  priorSummary: string;
  evidence: string;
}

interface Note {
  context: string;
  reflection: Reflection2;
  /** How many developer messages there had been when the agent received it. */
  deliveredAt: number;
}

interface Job {
  promptId: string;
  pair: Pair;
}

interface Settings {
  maxUSD: number;
  reflectionModel: string;
}

interface Usage {
  input_tokens?: number;
  output_tokens?: number;
  cache_read_input_tokens?: number;
  cache_creation_input_tokens?: number;
}

interface ModelRequest {
  model: string;
  system: readonly { text: string; cache?: true }[];
  prompt: string;
  maxTokens: number;
  effort?: "low" | "medium" | "high" | "xhigh" | "max";
  timeoutMs: number;
}

type Completion =
  | { isAnswered: true; text: string; usage?: Usage }
  | { isAnswered: false; reason: string; status?: number | null; usage?: Usage };

/**
 * What the judge and the reflection need from Claude Code. They run on a timer
 * after the hook that queued them has returned, and a hook may name the engine
 * only in a call written out where it is made, so session.start binds these
 * four calls once and the background work goes through them.
 */
interface Engine {
  complete(request: ModelRequest): Promise<Completion>;
  log(text: string): void;
  debug(text: string): void;
  soon(fn: () => void): void;
}

/** What reflect knows about the current session. Nothing here is written anywhere. */
class Session {
  /** Developer messages in order, by id: the turns the trigger counts. */
  prompts: string[] = [];
  /** What the agent has done since the developer last spoke. */
  calls: ToolCall[] = [];
  said = "";
  hasAgentTurn = false;
  verdicts = new Map<string, Verdict>();
  texts = new Map<string, TurnText>();
  fires: Array<{ promptId: string; evidence: string[] }> = [];
  spentUSD = 0;
  /** Set when the model calls stop for the rest of the session. */
  stopped: string | null = null;
  pending: Omit<Note, "deliveredAt"> | null = null;
  active: Note | null = null;
  /** Input tokens of the session's last response, when a note in force was last checked. */
  lastTokens: number | undefined = undefined;
  jobs: Job[] = [];
  draining: Promise<void> | null = null;
  judgeModel = DEFAULT_JUDGE_MODEL;
}

let session = new Session();
let engine: Engine | null = null;

export const register: Register = (on, options) => {
  const maxUSD = options["max_usd_per_session"];
  const model = options["reflection_model"];
  const settings: Settings = {
    maxUSD: typeof maxUSD === "number" && maxUSD > 0 ? maxUSD : DEFAULT_MAX_USD,
    reflectionModel: typeof model === "string" && model.trim() ? model.trim() : DEFAULT_REFLECTION_MODEL,
  };

  on("session.start", async ($, e, next) => {
    engine = {
      complete: (request) => $.model.complete(request),
      log: (text) => $.ui.log(text),
      debug: (text) => $.ui.log(text, { to: "debug" }),
      soon: (fn) => {
        $.clock.after(0, fn);
      },
    };
    try {
      await $.command.register({
        name: STATUS_COMMAND,
        description: "Show what reflect has judged, written and spent in this session",
        immediate: true,
      });
    } catch {
      // The command is a convenience; judging goes on without it.
    }
    return next(e);
  });

  // It only reads what is in memory, so it can answer while a turn is running.
  on("command.run", { command: STATUS_COMMAND }, async () => ({ text: statusText(settings) })).catch(() => ({
    text: "reflect could not show its status.",
  }));

  on("session.end", async ($, e, next) => {
    session = new Session();
    return next(e);
  });

  on("prompt.submit", async ($, e, next) => {
    // The same four calls, for a plugin turned on after its session started.
    engine ??= {
      complete: (request) => $.model.complete(request),
      log: (text) => $.ui.log(text),
      debug: (text) => $.ui.log(text, { to: "debug" }),
      soon: (fn) => {
        $.clock.after(0, fn);
      },
    };
    // Only the developer's own messages are judged. A background task's
    // notification, a scheduled prompt, another session's or a plugin's
    // message is passed on unread.
    if (e.isMeta) return next(e);
    const origin = (e as { origin?: { kind?: string } }).origin?.kind;
    if (origin !== undefined && !DEVELOPER_ORIGINS.has(origin)) return next(e);
    // A slash command with nothing after it is not the developer answering
    // the agent, and reflect's own command never is.
    const command = (e as { command?: { command?: string; args?: string } }).command;
    if (command && (command.command === STATUS_COMMAND || (command.args ?? "").trim().length < MIN_PROMPT_CHARS)) return next(e);
    const text = stripWrappers(e.text ?? "");
    // A bare `/compact` or `/clear` is not the developer answering the agent:
    // the agent's turn stays open and the next real message is judged against it.
    if (text.length < MIN_PROMPT_CHARS || isBookkeeping(text)) return next(e);

    queueJudgement(text, settings);

    let tokens: number | undefined;
    if (noteInPlay()) {
      try {
        tokens = tokensOf(await $.session.usage());
      } catch {
        // The figure only helps notice a compaction.
      }
    }
    const note = takeNote(tokens);
    if (!note) return next(e);
    $.ui.log(note.shown);
    return next({ ...e, context: [...(e.context ?? []), note.context] });
  }).catch(($, e, next) => next(e));

  // What the agent did: each main-loop tool call's name, target and whether it failed.
  on("tool.call", async ($, e, next) => {
    const r = await next(e);
    if (e.agentId !== undefined) return r;
    try {
      recordCall(String(e.tool), e as unknown as Record<string, unknown>, r.deny !== undefined || r.isError === true);
    } catch {
      // Recording is best effort; the tool's result goes back unchanged.
    }
    if (r.deny !== undefined || !noteInPlay()) return r;
    let tokens: number | undefined;
    try {
      tokens = tokensOf(await $.session.usage());
    } catch {
      // The figure only helps notice a compaction.
    }
    const note = takeNote(tokens);
    if (!note) return r;
    $.ui.log(note.shown);
    return { ...r, context: [...(r.context ?? []), note.context] };
  }).catch(($, e, next) => next(e));

  // What the agent said as it ended its turn.
  on("turn.complete", async ($, e, next) => {
    const r = await next(e);
    const { agentId, answer } = e as { agentId?: string; answer?: unknown };
    if (agentId === undefined && typeof answer === "string") {
      const s = session;
      const clean = redactString(answer).trim();
      if (clean) s.said = safeTruncateEnd(s.said ? `${s.said}\n\n${clean}` : clean, MAX_AGENT_TEXT);
      s.hasAgentTurn = true;
    }
    return r;
  });
};

// ─── The session's record ─────────────────────────────────────────────

/** Number the message, pair it with the agent's turn before it, and queue the judge. */
function queueJudgement(text: string, settings: Settings): void {
  const s = session;
  const promptId = `p${s.prompts.length + 1}`;
  s.prompts.push(promptId);
  const pair: Pair = {
    pairId: promptId,
    sessionId: "",
    project: "",
    promptIndex: s.prompts.length - 1,
    prompt: text,
    promptAt: null,
    prior: s.hasAgentTurn ? { text: s.said, toolCalls: s.calls, endedAt: null } : null,
    recentTargets: [],
    sidechain: false,
  };
  s.calls = [];
  s.said = "";
  s.hasAgentTurn = false;
  s.jobs.push({ promptId, pair });
  startWork(settings);
}

function recordCall(name: string, args: Record<string, unknown>, errored: boolean): void {
  const s = session;
  s.calls.push({
    name: safeTruncate(name, 80),
    target: safeTruncate(redactString(toolTarget(name, args)), 200),
    mutating: isMutating(name, args),
    errored,
  });
  if (s.calls.length > MAX_CALLS_PER_TURN) s.calls.splice(0, s.calls.length - MAX_CALLS_PER_TURN);
  s.hasAgentTurn = true;
}

// ─── Status ───────────────────────────────────────────────────────────

/** What `/reflect-status` prints. The agent reads it too, so it stays short. */
function statusText(settings: Settings): string {
  const s = session;
  const byLabel = new Map<string, number>();
  for (const v of s.verdicts.values()) if (isPushback(v.label)) byLabel.set(v.label, (byLabel.get(v.label) ?? 0) + 1);
  const pushbacks = [...byLabel.values()].reduce((a, b) => a + b, 0);
  const detail = pushbacks ? ` (${[...byLabel].map(([label, n]) => `${label} ${n}`).join(", ")})` : "";
  const lines = [
    "reflect in this session (kept in memory, gone when the session ends):",
    `- messages: ${s.prompts.length}, judged ${s.verdicts.size}${s.jobs.length ? `, ${s.jobs.length} waiting` : ""}`,
    `- pushback: ${pushbacks}${detail}`,
    `- notes written: ${s.fires.length}`,
    `- spent: $${s.spentUSD.toFixed(4)} of the $${settings.maxUSD.toFixed(2)} cap`,
  ];
  const left = s.active ? s.active.reflection.expires_after_turns - (s.prompts.length - s.active.deliveredAt) : 0;
  if (s.pending) lines.push("- a note is ready and goes to the agent with its next step");
  else if (s.active && left > 0) {
    const adj = s.active.reflection.adjustment;
    const shown = adj.length > 300 ? `${safeTruncate(adj, 300)}…` : adj;
    lines.push(`- note in force for ${left} more message${left === 1 ? "" : "s"}: ${shown}`);
  }
  else lines.push("- no note in force");
  if (s.stopped) lines.push(`- stopped: ${s.stopped}`);
  return lines.join("\n");
}

// ─── Delivery ─────────────────────────────────────────────────────────

/** Whether a note is waiting to go or still in force. */
function noteInPlay(): boolean {
  return session.pending !== null || session.active !== null;
}

/** Input tokens of the session's last response, from the figures the status line shows. */
function tokensOf(usage: unknown): number | undefined {
  const t = (usage as { context?: { tokens?: unknown } } | undefined)?.context?.tokens;
  return typeof t === "number" ? t : undefined;
}

/**
 * The note the agent should receive now, if any, and the line that shows it to
 * the developer. `tokens` is the session's context size, when Claude Code says.
 */
function takeNote(tokens: number | undefined): { context: string; shown: string } | null {
  const s = session;
  if (s.active && s.prompts.length - s.active.deliveredAt >= s.active.reflection.expires_after_turns) s.active = null;
  if (s.pending) {
    s.active = { ...s.pending, deliveredAt: s.prompts.length };
    s.pending = null;
    s.lastTokens = tokens;
    return { context: s.active.context, shown: `${SHOWN_HEAD}\n\n${s.active.context}` };
  }
  if (!s.active || tokens === undefined) return null;
  // A compaction drops the note from what the agent reads. reflect does not
  // read the conversation to see one: the context falling below half its size
  // says it, and the note goes again while it is in force.
  const before = s.lastTokens;
  s.lastTokens = tokens;
  if (before === undefined || before < COMPACTION_FLOOR_TOKENS || tokens >= before * COMPACTED_BELOW) return null;
  return { context: s.active.context, shown: `${SHOWN_AGAIN}\n\n${s.active.context}` };
}

// ─── Model calls ──────────────────────────────────────────────────────

/**
 * Judge the queued messages one at a time on a timer, after the hook that
 * queued them, so the developer's message is never held up by a model call.
 */
function startWork(settings: Settings): void {
  const s = session;
  const eng = engine;
  if (s.draining || !eng) return;
  const run = async () => {
    try {
      while (s.jobs.length && s === session) await judgeJob(eng, s, s.jobs.shift() as Job, settings);
    } finally {
      s.draining = null;
      if (s.jobs.length && s === session) startWork(settings);
    }
  };
  s.draining = new Promise<void>((resolve) => {
    eng.soon(() => {
      void run().then(resolve, resolve);
    });
  });
}


function costOf(model: string, u: Usage | undefined): number {
  if (!u) return 0;
  return capCostUSD(ALIAS_PRICED_AS[model] ?? model, {
    inputTokens: u.input_tokens ?? 0,
    outputTokens: u.output_tokens ?? 0,
    cacheReadTokens: u.cache_read_input_tokens ?? 0,
    cacheCreation5mTokens: u.cache_creation_input_tokens ?? 0,
  });
}

const errorText = (e: unknown): string => safeTruncate(redactString(String(e instanceof Error ? e.message : e)), 160);

/** Stop calling models for the rest of the session and say why, once. */
function stop(eng: Engine, s: Session, why: string): void {
  if (s.stopped) return;
  s.stopped = why;
  eng.log(`reflect stopped for this session: ${why}`);
}

/**
 * One completion. A model the engine will not send to (not allowed here, or an
 * id this provider does not know) is tried once more under its alias.
 */
async function complete(eng: Engine, request: ModelRequest, alias: string): Promise<{ r: Completion; model: string }> {
  try {
    return { r: await eng.complete(request), model: request.model };
  } catch (first) {
    if (request.model === alias) throw first;
    return { r: await eng.complete({ ...request, model: alias }), model: alias };
  }
}

function failed(eng: Engine, s: Session, what: string, r: Completion): void {
  if (r.isAnswered) return;
  if (r.reason === "api-error" && (r.status === 401 || r.status === 403)) {
    stop(eng, s, `the ${what} call was refused (HTTP ${r.status}).`);
    return;
  }
  eng.debug(`reflect: the ${what} call returned no answer (${r.reason}${r.status ? ` ${r.status}` : ""}).`);
}

async function judgeJob(eng: Engine, s: Session, job: Job, settings: Settings): Promise<void> {
  const { promptId, pair } = job;
  // No agent turn before this message (the session's first, or two messages in
  // a row): nothing to push back on, and no model call.
  if (!pair.prior || s.stopped) return;
  if (s.spentUSD >= settings.maxUSD) return stop(eng, s, `it reached its spend cap of $${settings.maxUSD.toFixed(2)}.`);

  let call: { r: Completion; model: string };
  try {
    call = await complete(
      eng,
      {
        model: s.judgeModel,
        system: [{ text: JUDGE_SYSTEM, cache: true }],
        prompt: `${buildUserMessage(pair, false)}\n\n${answerAsJson(VERDICT_SCHEMA)}`,
        maxTokens: 2000,
        // The measured judge runs at low effort with thinking off. Left unset,
        // the engine would use the model's own default effort.
        effort: "low",
        timeoutMs: 30_000,
      },
      "haiku",
    );
  } catch (e) {
    return stop(eng, s, `the judge model could not be called (${errorText(e)}).`);
  }
  const { r, model } = call;
  s.judgeModel = model;
  s.spentUSD += costOf(model, r.usage);
  if (!r.isAnswered) return failed(eng, s, "judge", r);
  let verdict: JudgeVerdict;
  try {
    verdict = parseLoose(r.text, parseVerdict);
  } catch (e) {
    // One unreadable answer skips this message. It does not stop the session.
    eng.debug(`reflect: the judge's answer could not be read (${errorText(e)}); this message was not judged.`);
    return;
  }

  s.verdicts.set(promptId, { label: verdict.label, confidence: verdict.confidence });
  const prior = renderPriorTurn(pair);
  s.texts.set(promptId, {
    prompt: safeTruncate(redactString(pair.prompt), 1500),
    priorSummary: prior.length > 2000 ? "…" + safeTruncateEnd(prior, 2000) : prior,
    evidence: redactString(verdict.evidence),
  });
  for (const id of [...s.texts.keys()].slice(0, Math.max(0, s.texts.size - KEPT_TEXTS))) s.texts.delete(id);

  // A verdict that is not pushback cannot complete a pattern.
  if (!isPushback(verdict.label)) return;

  // Replay the trigger over the session. Turns that already took part in a
  // fire never trip a second one.
  const fired = new Set(s.fires.map((f) => f.promptId));
  const used = new Set(s.fires.flatMap((f) => f.evidence));
  const acc = new Accumulator(POLICY);
  let hit: { promptId: string; evidence: string[] } | null = null;
  for (const id of s.prompts) {
    const v = s.verdicts.get(id);
    const fire = acc.observe(id, v && isPushback(v.label) ? { label: v.label, confidence: v.confidence } : null);
    if (fire && !fired.has(id) && fire.evidence.includes(promptId) && !fire.evidence.some((x) => used.has(x))) {
      hit = { promptId: id, evidence: fire.evidence };
    }
  }
  if (!hit) return;
  s.fires.push(hit);
  await reflectOn(eng, s, hit.evidence, settings);
}

async function reflectOn(eng: Engine, s: Session, evidence: string[], settings: Settings): Promise<void> {
  if (s.stopped) return;
  // The reflection costs far more than a judgement, so check the cap again.
  if (s.spentUSD >= settings.maxUSD) return stop(eng, s, `it reached its spend cap of $${settings.maxUSD.toFixed(2)}.`);
  const turns: EvidenceTurn[] = [];
  for (const id of evidence) {
    const v = s.verdicts.get(id);
    const t = s.texts.get(id);
    if (!v || !t) continue;
    turns.push({ turn: s.prompts.indexOf(id) + 1, label: v.label, confidence: v.confidence, ...t });
  }
  if (turns.length === 0) return;

  let reflection: Reflection2;
  try {
    const { r, model } = await complete(
      eng,
      {
        model: settings.reflectionModel,
        system: [{ text: REFLECTION_SYSTEM, cache: true }],
        prompt: `${buildReflectionInput(turns, POLICY.window)}\n\n${answerAsJson(REFLECTION_SCHEMA)}`,
        maxTokens: 8000,
        effort: DEFAULT_REFLECTION_EFFORT,
        timeoutMs: 180_000,
      },
      "opus",
    );
    s.spentUSD += costOf(model, r.usage);
    if (!r.isAnswered) return failed(eng, s, "reflection", r);
    reflection = parseLoose(r.text, parseReflection2);
  } catch (e) {
    eng.debug(`reflect: no reflection (${errorText(e)}).`);
    return;
  }
  if (s !== session) return;
  s.pending = {
    reflection,
    context: formatForAgent(reflection, { pushbacks: turns.length, window: POLICY.window, turns: turns.map((t) => t.turn) }),
  };
}
